import {createServer} from 'node:http';
import {loadBackendEnvironment} from './env.js';
import {createBackend} from './runtime.js';

let backend;
try{
 loadBackendEnvironment();
 backend=createBackend();
}catch(error){
 // Configuration errors are generated by our validators, not provider responses.
 console.error('Backend configuration failed. Check NODE_ENV, PORT, HOST, HTTPS APP_ORIGIN, boolean flags and private Gemini/Supabase settings.');
 process.exitCode=1;
}
if(backend){
 const server=createServer(backend.handler);
 server.requestTimeout=60_000;
 server.headersTimeout=10_000;
 let stopping=false;
 const release=()=>backend.close();
 server.on('error',error=>{
  console.error(`Local server could not start (${['EADDRINUSE','EACCES','EPERM','EADDRNOTAVAIL'].includes(error.code)?error.code:'START_FAILED'}). Check local port/network permissions.`);
  release();process.exitCode=1;
 });
 server.on('close',release);
 server.listen(backend.port,backend.host,()=>{
  const host=backend.host.includes(':')?`[${backend.host}]`:backend.host;
  console.log(`KapasMitra backend: http://${host}:${backend.port}`);
  console.log('Status: GET /api/health. Research infrastructure readiness: GET /api/ready.');
  console.log(`Research browsing: ${backend.publicResearchAccess?'public, with explicit public-sharing consent':'approved accounts'}`);
 });
 for(const signal of ['SIGINT','SIGTERM'])process.once(signal,()=>{
  if(stopping)return;stopping=true;
  const deadline=setTimeout(()=>{server.closeAllConnections();release();process.exitCode=1;},5000);deadline.unref();
  server.close(()=>{clearTimeout(deadline);release();});
 });
}
